', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' ELSE 'NA' END AS search_day, s.user_type, s.os, s.channel, s.src_id, s.dest_id, s.doj FROM "user_interaction"."search_route_details" s -- INNER JOIN target_routes t ON s.src_id = t.src_id AND s.dest_id = t.dest_id WHERE s.__time >= TIMESTAMP '2026-01-13 18:30:00' AND s.__time < TIMESTAMP '2026-01-20 18:30:00' -- AND (s.src_id, s.dest_id) IN ((69283, 65782)) -- AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.os = 'Android' AND s.country = 'IND' AND s.status = 200 AND app_code = 812070 -- AND -- LIMIT 100 -- GROUP BY 1,2,3,4,5,6,7,8,9 ), viewed AS ( SELECT DISTINCT CAST(DATE_TRUNC('day', date_add('minute', 330, "__time")) AS DATE) AS doi, event_group, event_name, event_value, usertype, mri_session_id viewed_session FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' AND event_group IN ('great_india_sales', 'India_sale_view_all_loaded', 'India_sale_section_clicked', 'India_sale_section_loaded') -- AND event_name in ('India_sale_section') AND event_value = 'viewed' -- AND sort_label IN ('INDIA_SALE_HANDPICKED') -- and app_version>='81.2' ), clicked AS ( SELECT DISTINCT event_group, event_name, event_value, usertype, mri_session_id clicked_session FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' AND event_group IN ('great_india_sales', 'India_sale_view_all_loaded', 'India_sale_section_clicked', 'India_sale_section_loaded') -- AND event_name in ('India_sale_section') AND event_value IN ('clicked', 'view_all_clicked') -- AND sort_label IN ('INDIA_SALE_HANDPICKED') -- and app_version>='81.2' ), sl_lands AS ( SELECT DISTINCT mri_session_id FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND event_name = 'India_sale_load_animation_shown' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' -- LIMIT 20 ), Tuples AS ( SELECT DISTINCT srd.mri_session_id AS srpsession, route_id FROM "user_interaction"."search_route_details" srd WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND total_ratings >= 3.0 AND os = 'Android' -- AND mri_session_id = 'AMaab40f36-fd15-3802-afa5-c06d2cc7d22b' -- AND (src_id, dest_id) IN ((69283, 65782)) -- AND (src_id, dest_id) IN (SELECT source_id, destination_id FROM top_bharat_sds) AND country = 'IND' ), avg_tuples AS ( SELECT srpsession, COUNT(DISTINCT route_id) route_id_count FROM Tuples GROUP BY 1 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND os = 'Android' AND country = 'IND' AND status = 200 GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), addpay_deduped AS ( SELECT mri_session_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."make_payment_details" WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND os = 'Android' -- AND status = 200 AND akamai_bot IS NOT NULL AND country = 'IND' GROUP BY 1 ), confirm AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-01-13 18:30:00' AND __time < TIMESTAMP '2026-01-20 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') -- AND status = 200 AND akamai_bot IS NOT NULL -- AND os = 'Android' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT v.doi, -- v.event_name, -- s.search_day, v.usertype, '' overall_srp_sessions, '' dbs_srp, COUNT(DISTINCT v.viewed_session) AS viewed_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'clicked' THEN c.clicked_session END) AS clicked_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN c.clicked_session END) AS view_all_clicked_sessions, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN t.route_id END) AS Unique_DBS_Tuples_Loaded, ROUND(AVG(avg_t.route_id_count),2) AS Average_dbs_tuples_per_session, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN sl.mri_session_id END) AS dbs_SL_Lands, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN ci.mri_session_id END) AS overall_custInfo_Lands, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' AND ci.route_id = t.route_id THEN ci.mri_session_id END) AS dbs_custInfo_Lands, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' THEN con.mri_session_id END) AS overall_con_Lands, COUNT(DISTINCT CASE WHEN c.event_value = 'view_all_clicked' AND con.route_id = t.route_id THEN con.mri_session_id END) AS dbs_con_Lands FROM srp_deduped s INNER JOIN viewed v ON s.mri_session_id = v.viewed_session LEFT JOIN clicked c ON v.viewed_session = c.clicked_session LEFT JOIN Tuples t ON t.srpsession = c.clicked_session LEFT JOIN avg_tuples avg_t ON avg_t.srpsession = c.clicked_session LEFT JOIN sl_lands sl ON sl.mri_session_id = c.clicked_session LEFT JOIN mpax_deduped ci ON ci.mri_session_id = c.clicked_session LEFT JOIN confirm con ON con.mri_session_id = c.clicked_session GROUP BY 1,2,3,4 ORDER BY 1, 2 DESC
